def count_routes(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    routes = [[0] * cols for _ in range(rows)]      # a fresh list per row

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                continue                            # blocked stays 0
            if r == 0 and c == 0:
                routes[0][0] = 1                    # the only base case
                continue
            above = routes[r - 1][c] if r > 0 else 0
            left = routes[r][c - 1] if c > 0 else 0
            routes[r][c] = above + left
    return routes[rows - 1][cols - 1]

