javascript.solution:
function countRoutes(grid) {
  if (grid.length === 0 || grid[0].length === 0) return 0;
  const rows = grid.length;
  const cols = grid[0].length;
  const routes = Array.from({ length: rows }, () => new Array(cols).fill(0));

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 1) continue;              // blocked stays 0
      if (r === 0 && c === 0) {
        routes[0][0] = 1;                          // the only base case
        continue;
      }
      const above = r > 0 ? routes[r - 1][c] : 0;
      const left = c > 0 ? routes[r][c - 1] : 0;
      routes[r][c] = above + left;
    }
  }
  return routes[rows - 1][cols - 1];
}
